const STORAGE_KEY = 'fluentpath-demo-v1';

const courses = [
  { id: 'conversation', title: 'Conversational English', category: 'Everyday Fluency', level: 'Intermediate', lessons: 18, duration: '6 weeks', rating: '4.9', students: '18.4k', cover: 'violet', symbol: '💬', description: 'Sound natural in real conversations, from first introductions to thoughtful opinions.', objective: ['Build confident conversation habits', 'Use useful expressions naturally', 'Improve listening in everyday speech'] },
  { id: 'business', title: 'English for Modern Work', category: 'Business English', level: 'Advanced', lessons: 24, duration: '8 weeks', rating: '4.8', students: '12.1k', cover: 'blue', symbol: '📊', description: 'Lead meetings, write clear emails, and make your ideas land with confidence.', objective: ['Lead clear, concise meetings', 'Write polished workplace messages', 'Handle difficult conversations'] },
  { id: 'ielts', title: 'IELTS Confidence Builder', category: 'IELTS & TOEFL', level: 'Advanced', lessons: 30, duration: '10 weeks', rating: '4.9', students: '24.7k', cover: 'yellow', symbol: '🎓', description: 'A focused path through the skills and strategies behind a strong IELTS result.', objective: ['Understand exam task types', 'Structure high-scoring responses', 'Build test-day confidence'] },
  { id: 'foundations', title: 'English Foundations', category: 'Everyday Fluency', level: 'Beginner', lessons: 16, duration: '5 weeks', rating: '4.7', students: '31.2k', cover: 'mint', symbol: '🌱', description: 'Start speaking from day one with practical vocabulary and friendly grammar practice.', objective: ['Create simple, accurate sentences', 'Talk about everyday routines', 'Grow a useful core vocabulary'] }
];

const lessons = ['Small talk that feels easy', 'Questions that keep it going', 'The art of active listening', 'Sharing your point of view', 'A confident conversation'];
const quizQuestions = [
  { question: 'Choose the natural phrase: “I have lived here ___ 2022.”', options: ['for', 'since', 'during', 'from'], answer: 1, explanation: 'Use “since” with a starting point in time.' },
  { question: 'What does “serendipity” describe?', options: ['A planned achievement', 'A difficult decision', 'A pleasant discovery by chance', 'A quick conversation'], answer: 2, explanation: 'Serendipity is finding something good unexpectedly.' },
  { question: 'Complete the sentence: “If I had more time, I ___ another language.”', options: ['learn', 'will learn', 'would learn', 'am learning'], answer: 2, explanation: 'The second conditional uses would + base verb.' },
  { question: 'Which response sounds most natural? “Would you mind opening the window?”', options: ['Yes, I mind.', 'Not at all.', 'I open it yesterday.', 'No, I would.'], answer: 1, explanation: '“Not at all” is a polite way to say you are happy to help.' },
  { question: 'Choose the best word: “The presentation was clear and ___.”', options: ['persuade', 'persuasion', 'persuasive', 'persuading'], answer: 2, explanation: 'Persuasive is the adjective that describes something convincing.' },
  { question: 'What is the speaker implying? “I’m not sure that is the best approach.”', options: ['Full agreement', 'A polite disagreement', 'A request for directions', 'Excitement'], answer: 1, explanation: 'This is a soft, professional way to disagree.' },
  { question: 'Complete the sentence: “By the time we arrived, the meeting ___.”', options: ['starts', 'has started', 'had started', 'will start'], answer: 2, explanation: 'Use past perfect for an action completed before another past action.' },
  { question: 'Which phrase best continues this conversation? “I’ve just started a new course.”', options: ['That sounds interesting. What are you studying?', 'I started yesterday too.', 'You must course it.', 'No, I don’t.'], answer: 0, explanation: 'A natural follow-up question shows interest and keeps the conversation moving.' }
];

const defaultState = { user: null, level: null, enrolled: [], completedLessons: [], xp: 420, streak: 6, lastStudy: null, history: [], notifications: 2, savedWords: [], quizScore: null, achievements: ['streak'], profile: { name: 'Alex Morgan', email: 'alex@example.com' } };
let state = loadState();
let selectedLevel = state.level || 'Intermediate';
let quizIndex = 0;
let quizAnswers = {};
let flashcardFlipped = false;

function uiIcon(symbol) { const paths = { home: '<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>', grid: '<rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><rect x="14" y="14" width="6" height="6" rx="1"/>', practice: '<circle cx="12" cy="12" r="8"/><path d="m12 8 2.5 4-2.5 4-2.5-4z"/>', progress: '<path d="M5 19 19 5"/><path d="M10 5h9v9"/>', history: '<path d="M5 6h14M5 12h14M5 18h14"/><circle cx="3" cy="6" r=".7"/><circle cx="3" cy="12" r=".7"/><circle cx="3" cy="18" r=".7"/>', bell: '<path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>', settings: '<path d="M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6 7 7M17 17l1.4 1.4M18.4 5.6 17 7M7 17l-1.4 1.4"/><circle cx="12" cy="12" r="4"/>', listen: '<path d="M4 10v4M8 7v10M12 4v16M16 7v10M20 10v4"/>', text: '<path d="M5 5h14M12 5v14M8 19h8"/>', mic: '<rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3M8 21h8"/>', spark: '<path d="m12 3 1.5 6.5L20 12l-6.5 2.5L12 21l-1.5-6.5L4 12l6.5-2.5z"/>', clock: '<circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/>', arrow: '<path d="M5 19 19 5M10 5h9v9"/>' }; const aliases = { '⌂':'home', '▦':'grid', '◉':'practice', '↗':'progress', '☷':'history', '◒':'listen', 'Aa':'text', '◌':'mic', '✦':'spark', '◷':'clock' }; const path = paths[aliases[symbol] || symbol] || paths.spark; return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`; }

function loadState() { try { return { ...defaultState, ...JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}') }; } catch { return { ...defaultState }; } }
function saveState() { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); }
function initials(name = 'Alex Morgan') { return name.split(' ').map(part => part[0]).join('').slice(0, 2).toUpperCase(); }
function currentRoute() { return location.hash.replace('#', '') || (state.user ? 'home' : 'welcome'); }
function escapeHtml(value) { return String(value).replace(/[&<>'"]/g, char => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#039;', '"':'&quot;' }[char])); }
function toast(message) { const element = document.querySelector('#toast'); element.textContent = message; element.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(() => element.classList.remove('show'), 2800); }
function addHistory(type, title, detail, icon = '✓') { const key = `${type}:${title}`; if (state.history.some(item => item.key === key)) return; state.history.unshift({ key, type, title, detail, icon, date: new Date().toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) }); saveState(); }
function awardXP(amount, reason) { state.xp += amount; if (reason) addHistory('xp', reason, `+${amount} XP earned`, '⚡'); saveState(); }
function ensureAchievement(id, name, description) { if (!state.achievements.includes(id)) { state.achievements.push(id); saveState(); toast(`Achievement unlocked: ${name}`); addHistory('achievement', name, description, '✦'); } }
function navigate(route) { location.hash = route; }

function navButton(route, icon, label) { return `<button class="nav-button ${currentRoute() === route ? 'active' : ''}" data-route="${route}"><span class="nav-icon">${uiIcon(icon)}</span><span>${label}</span></button>`; }
function shell(content, title = '') { return `<div class="app-shell"><aside class="sidebar"><div class="logo"><span class="logo-mark">F</span> FluentPath</div><div><div class="eyebrow" style="color:#aaa5d2;padding:0 13px 10px">Your learning space</div><nav class="nav-list">${navButton('home','⌂','Home')}${navButton('courses','▦','Courses')}${navButton('practice','◉','Practice')}${navButton('progress','↗','Progress')}${navButton('history','☷','History')}</nav></div><div class="sidebar-foot"><button class="nav-button" data-route="profile">⚙ <span>Profile & settings</span></button><div class="profile-mini"><span class="avatar">${initials(state.profile.name)}</span><span class="mini-copy"><strong>${escapeHtml(state.profile.name)}</strong><span>${state.level || 'Choose a level'}</span></span></div></div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">${title || 'FluentPath'}</div></div><div class="top-actions"><button class="icon-button" data-action="notifications" aria-label="Notifications">♢${state.notifications ? '<span class="badge-dot"></span>' : ''}</button><button class="profile-button" data-route="profile" aria-label="Open profile"><span class="avatar">${initials(state.profile.name)}</span></button></div></header>${content}</main><nav class="mobile-nav">${navButton('home','⌂','Home')}${navButton('courses','▦','Courses')}${navButton('practice','◉','Practice')}${navButton('progress','↗','Progress')}${navButton('history','☷','History')}</nav></div>`; }
function page() { const route = currentRoute(); const routeName = route.split('?')[0]; if (!state.user && routeName !== 'welcome' && routeName !== 'onboarding') navigate('welcome'); const views = { home: renderHome, courses: renderCourses, practice: renderPractice, progress: renderProgress, history: renderHistory, profile: renderProfile, welcome: renderWelcome, onboarding: renderOnboarding, lesson: renderLesson, quiz: renderQuiz, 'quiz-result': renderQuizResult, course: renderCourseDetails, notifications: renderNotifications }; let view = views[routeName] || renderHome; if (routeName.startsWith('practice-')) view = () => renderPracticeMode(routeName.replace('practice-', '')); document.querySelector('#app').innerHTML = state.user || ['welcome','onboarding'].includes(routeName) ? view() : renderWelcome(); bindEvents(); }

function renderWelcome() { return `<div class="onboarding"><div class="onboarding-panel"><section class="onboarding-copy"><div><div class="logo"><span class="logo-mark">F</span> FluentPath</div><div class="onboarding-art">✦</div><h1>Your English, in motion.</h1><p>A focused, friendly path to speak with more confidence every day.</p></div><small style="color:#aaa5d2">A simulated learning experience for your next chapter.</small></section><section class="onboarding-form"><div class="eyebrow">Welcome to FluentPath</div><h2>Make progress feel personal.</h2><p>Build a habit around the English you actually want to use.</p><div class="stack" style="margin-top:28px"><button class="button button-primary" data-route="onboarding">Get started <span>→</span></button><button class="button button-secondary" data-action="demo-login">Explore demo dashboard</button></div><p class="small" style="margin-top:30px">By continuing, you’re using a demo account. No real authentication is connected.</p></section></div></div>`; }
function renderOnboarding() { return `<div class="onboarding"><div class="onboarding-panel"><section class="onboarding-copy"><div><div class="logo"><span class="logo-mark">F</span> FluentPath</div><div class="onboarding-art">🧭</div><h1>Find your right pace.</h1><p>Tell us where you are starting. Your path can change as you grow.</p></div></section><section class="onboarding-form"><div class="eyebrow">Step 1 of 1</div><h2>What feels like you?</h2><p>Choose a starting level. This only personalizes your demo recommendations.</p><div class="level-grid">${[['Beginner','A1–A2','Build foundations with practical phrases.','🌱'],['Intermediate','B1–B2','Find your voice in everyday conversations.','🌿'],['Advanced','C1–C2','Sharpen nuance, fluency, and precision.','🌳']].map(([name,range,desc,emoji]) => `<button class="level-card ${selectedLevel === name ? 'selected' : ''}" data-level="${name}"><span class="level-emoji">${emoji}</span><span><strong>${name} <span class="muted">${range}</span></strong><p>${desc}</p></span></button>`).join('')}</div><button class="button button-primary" data-action="finish-onboarding" style="width:100%">Create my learning path →</button><button class="button button-ghost" data-route="welcome" style="width:100%;margin-top:9px">Back</button></section></div></div>`; }

function renderHome() { const percent = Math.min(100, Math.round((state.xp % 500) / 5)); const enrolled = courses.find(course => state.enrolled.includes(course.id)) || courses[0]; return shell(`<section class="hero"><div class="eyebrow" style="color:#b8a9ff">${state.level} path · Week ${state.streak}</div><h1>Good morning, ${escapeHtml(state.profile.name.split(' ')[0])}.</h1><p>Your consistency is doing the heavy lifting. A small session today keeps your English moving forward.</p><button class="button" style="background:var(--yellow);color:var(--navy);margin-top:8px" data-route="lesson">Resume lesson →</button><div class="hero-meta"><span><strong>${state.streak} days</strong>current streak</span><span><strong>${state.xp} XP</strong>total earned</span><span><strong>${state.completedLessons.length}/5</strong>lessons completed</span></div></section><div class="grid grid-4"><div class="card stat"><div><div class="stat-label">Today’s focus</div><div class="stat-value">12 <small class="small muted">/ 15 min</small></div></div><span class="stat-icon">◷</span></div><div class="card stat"><div><div class="stat-label">Weekly XP</div><div class="stat-value">${state.xp % 700 + 180}</div></div><span class="stat-icon" style="background:#e5f1ff">⚡</span></div><div class="card stat"><div><div class="stat-label">Words saved</div><div class="stat-value">${state.savedWords.length}</div></div><span class="stat-icon" style="background:#fff0c8">✦</span></div><div class="card stat"><div><div class="stat-label">Current level</div><div class="stat-value" style="font-size:1.12rem">${state.level}</div></div><span class="stat-icon" style="background:#d8f4e6">↗</span></div></div><div class="two-col"><div><div class="section-heading"><h2>Keep the rhythm</h2><span class="muted small">Your week</span></div><div class="card"><div class="stat"><div><h3>Daily learning goal</h3><p class="small">12 minutes complete today</p></div><strong>80%</strong></div><div class="progress-track"><div class="progress-fill blue" style="width:80%"></div></div><div class="week">${['M','T','W','T','F','S','S'].map((day,index) => `<div class="day ${index < 5 ? 'done' : ''} ${index === 5 ? 'today' : ''}"><span>${day}</span><span class="day-dot">${index < 5 ? '✓' : index === 5 ? '•' : ''}</span></div>`).join('')}</div></div></div><div><div class="section-heading"><h2>Word of the day</h2><span class="muted small">1 min</span></div><div class="card"><div class="eyebrow">serendipity · /ˌser.ənˈdɪp.ə.ti/</div><h3 style="font-size:1.5rem;margin-top:7px">A happy accident.</h3><p class="small">The occurrence of finding pleasant things by chance.</p><p class="small"><em>“Meeting my business partner was pure serendipity.”</em></p><button class="button button-secondary" data-action="save-word">${state.savedWords.includes('serendipity') ? '✓ Saved to vocabulary' : '+ Save word'}</button></div></div></div><div class="section-heading"><h2>Resume learning</h2><button class="button button-ghost" data-route="courses">View courses →</button></div><div class="card feature-card"><div class="feature-illustration">💬</div><div class="feature-copy"><small>${enrolled.title} · Unit 4</small><h3>${lessons[Math.min(state.completedLessons.length, lessons.length - 1)]}</h3><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100, state.completedLessons.length * 20 + 20)}%"></div></div><p class="small">${Math.max(1, 5 - state.completedLessons.length)} lessons left in this unit</p></div><button class="button button-primary" data-route="lesson">Continue</button></div><div class="section-heading"><h2>Choose your practice</h2><span class="muted small">Short sessions, real momentum</span></div><div class="grid grid-4">${practiceCards()}</div>`, 'Home'); }
function practiceCards() { return [['listening','◒','Speed listening','Train your ear for natural rhythm.','8 min','Listening'],['grammar','Aa','Grammar sprint','Make the right structure feel automatic.','5 min','Grammar'],['speaking','◌','Speaking coach','Practice a useful conversation out loud.','6 min','Speaking'],['vocabulary','✦','Vocabulary practice','Meet five words you’ll remember.','4 min','Vocabulary']].map(([id,icon,title,desc,time,tag]) => `<article class="card practice-card"><div class="practice-top"><span class="practice-icon">${icon}</span><span class="tag">${tag}</span></div><div><h3>${title}</h3><p class="small">${desc}</p></div><div class="stat-label">${time}<button class="button button-ghost" style="float:right" data-practice="${id}">Start →</button></div></article>`).join(''); }

function renderCourses() { return shell(`<div class="section-heading" style="margin-top:0"><div><h2>Find your next lesson</h2><p>Courses designed for the English you want to use.</p></div><span class="tag">${state.enrolled.length} enrolled</span></div><div class="filter-row"><input class="input search-input" id="course-search" placeholder="Search courses..." /><select class="select" id="course-category"><option value="all">All categories</option><option>Everyday Fluency</option><option>Business English</option><option>IELTS & TOEFL</option></select><select class="select" id="course-level"><option value="all">All levels</option><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></div><div class="grid grid-2" id="course-grid">${courseCards(courses)}</div>`, 'Courses'); }
function courseCards(items) { return items.length ? items.map(course => `<article class="card course-card"><div class="course-cover ${course.cover}"><span class="tag">${course.level}</span><span class="course-symbol">${course.symbol}</span></div><div class="course-body"><div class="eyebrow">${course.category}</div><h3>${course.title}</h3><p class="small">${course.description}</p><div class="course-meta"><span>★ ${course.rating} · ${course.students}</span><span>${course.duration}</span></div><div style="display:flex;gap:8px"><button class="button button-secondary" data-course-details="${course.id}">Details</button><button class="button button-primary" data-enroll="${course.id}">${state.enrolled.includes(course.id) ? 'Continue' : 'Enroll now'}</button></div></div></article>`).join('') : '<div class="card empty" style="grid-column:1/-1">No courses match that search. Try a broader path.</div>'; }
function renderCourseDetails() { const course = courses.find(item => item.id === (new URLSearchParams(location.hash.split('?')[1] || '').get('id')) || 'conversation') || courses[0]; const enrolled = state.enrolled.includes(course.id); return shell(`<button class="button button-ghost" data-route="courses">← Back to courses</button><div class="hero" style="margin-top:18px;background:${course.cover === 'blue' ? '#315e9b' : course.cover === 'mint' ? '#2d8061' : course.cover === 'yellow' ? '#8a6c26' : 'var(--navy)'}"><div class="eyebrow" style="color:#d9d1ff">${course.category} · ${course.level}</div><h1>${course.title}</h1><p>${course.description}</p><div class="hero-meta"><span><strong>${course.lessons}</strong>lessons</span><span><strong>${course.duration}</strong>course length</span><span><strong>★ ${course.rating}</strong>learner rating</span></div></div><div class="two-col"><div class="stack"><section class="card"><h3>What you’ll be able to do</h3>${course.objective.map(item => `<div class="activity"><span class="activity-icon">✓</span><span class="activity-copy"><strong>${item}</strong><span>Practical, repeatable progress</span></span></div>`).join('')}</section><section class="card"><div class="section-heading" style="margin:0 0 15px"><h3>Course curriculum</h3><span class="muted small">${state.completedLessons.length}/5 complete</span></div><div class="lesson-list">${lessons.map((lesson,index) => `<div class="lesson-row ${state.completedLessons.includes(index) ? 'done' : ''}"><span class="lesson-number">${state.completedLessons.includes(index) ? '✓' : index + 1}</span><span style="flex:1"><strong>${lesson}</strong><p>${index === 0 ? '6 min · Conversation' : '8 min · Guided practice'}</p></span><span class="muted small">${state.completedLessons.includes(index) ? 'Done' : index === state.completedLessons.length ? 'Next' : 'Locked'}</span></div>`).join('')}</div></section></div><section class="card"><div class="feature-illustration" style="width:100%;height:150px;margin-bottom:18px">${course.symbol}</div><h3>Ready when you are.</h3><p class="small">You’re using a demo course. Your progress is saved on this device.</p><button class="button button-primary" data-route="lesson" style="width:100%">${enrolled ? 'Continue course' : 'Start course'}</button></section></div>`, 'Course details'); }
function renderLesson() { const index = Math.min(state.completedLessons.length, lessons.length - 1); const completed = state.completedLessons.includes(index); return shell(`<div class="section-heading" style="margin-top:0"><div><button class="button button-ghost" data-route="home">← Dashboard</button><div class="eyebrow" style="margin-top:20px">Conversational English · Unit 4</div><h2>${lessons[index]}</h2></div><span class="tag">Lesson ${index + 1} of ${lessons.length}</span></div><div class="two-col"><article class="card"><div class="eyebrow">Today’s idea</div><h3 style="font-size:1.8rem;margin-top:9px">Good conversation is a shared rhythm.</h3><p>When you show curiosity, the other person has somewhere to go. Practice asking one more question, then listen for the detail that makes the conversation real.</p><div class="card" style="background:#f7f5ff;border:0;margin:25px 0"><p style="margin-bottom:7px;color:var(--navy)"><strong>Useful expression</strong></p><h3 style="margin:0">“That’s interesting. Tell me more about it.”</h3><p class="small" style="margin:8px 0 0">Use this when you want to invite someone to continue.</p></div><div class="card" style="background:#eef8ff;border:0"><p class="small" style="margin:0"><strong>Try it out loud:</strong> Think of a recent place you visited. Ask yourself one follow-up question.</p></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:25px;gap:10px"><span class="muted small">⏱ 6 minutes</span><button class="button button-primary" data-action="complete-lesson">${completed ? 'Lesson complete ✓' : 'Mark lesson complete'}</button></div></article><aside class="stack"><div class="card"><div class="stat"><div><h3>Your course progress</h3><p class="small">Keep a little space for English today.</p></div><strong>${Math.round((state.completedLessons.length / lessons.length) * 100)}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${Math.max(10, state.completedLessons.length / lessons.length * 100)}%"></div></div></div><div class="card"><h3>Lesson vocabulary</h3><div class="activity"><span class="activity-icon">✦</span><span class="activity-copy"><strong>curiosity</strong><span>the desire to learn or know</span></span><button class="icon-button" data-action="speak" data-text="curiosity">▶</button></div><div class="activity"><span class="activity-icon">✦</span><span class="activity-copy"><strong>follow-up</strong><span>a response that continues a topic</span></span><button class="icon-button" data-action="speak" data-text="follow up">▶</button></div></div></aside></div>`, 'Learning room'); }
function renderQuiz() { const question = quizQuestions[quizIndex]; const selected = quizAnswers[quizIndex]; return shell(`<div class="section-heading" style="margin-top:0"><div><div class="eyebrow">Diagnostic check · Demo assessment</div><h2>Find your next edge.</h2></div><span class="tag">Question ${quizIndex + 1} of ${quizQuestions.length}</span></div><div class="two-col"><section class="card"><div class="progress-track" style="margin:0 0 25px"><div class="progress-fill blue" style="width:${(quizIndex + 1) / quizQuestions.length * 100}%"></div></div><h3 style="font-size:1.4rem">${question.question}</h3><div>${question.options.map((option,index) => `<button class="quiz-option ${selected === index ? 'selected' : ''}" data-answer="${index}"><span class="option-key">${String.fromCharCode(65 + index)}</span>${option}</button>`).join('')}</div>${selected !== undefined ? `<div class="card" style="background:${selected === question.answer ? '#e9f8f0' : '#fff0ee'};border:0;margin-top:18px"><strong>${selected === question.answer ? 'Correct.' : 'Not quite.'}</strong><p class="small" style="margin:4px 0 0">${question.explanation}</p></div>` : ''}<div style="display:flex;justify-content:space-between;margin-top:25px"><button class="button button-ghost" data-action="quiz-back" ${quizIndex === 0 ? 'disabled' : ''}>← Previous</button>${quizIndex < quizQuestions.length - 1 ? `<button class="button button-primary" data-action="quiz-next" ${selected === undefined ? 'disabled' : ''}>Next question →</button>` : `<button class="button button-primary" data-action="submit-quiz" ${selected === undefined ? 'disabled' : ''}>See my result →</button>`}</div></section><aside class="card"><div class="eyebrow">Why this matters</div><h3>Small checks, useful direction.</h3><p class="small">This quick demo assessment estimates a CEFR starting point from your answers. It is not an official qualification.</p><div class="activity"><span class="activity-icon">◷</span><span class="activity-copy"><strong>About 3 minutes</strong><span>No pressure, just a signal</span></span></div></aside></div>`, 'Diagnostic test'); }
function renderQuizResultLegacy() { const score = state.quizScore || 0; const level = score === 3 ? 'B2 estimate' : score >= 2 ? 'B1 estimate' : 'A2 estimate'; return shell(`<div class="hero"><div class="eyebrow" style="color:#b8a9ff">Your demo result</div><h1>${level}</h1><p>You answered ${score} of ${quizQuestions.length} questions correctly. Use this as a friendly direction marker, not an official certification.</p><button class="button" style="background:var(--yellow);color:var(--navy)" data-route="courses">Explore a recommended course →</button></div><div class="grid grid-3"><div class="card stat"><div><div class="stat-label">Grammar</div><div class="stat-value">${Math.min(98, 58 + score * 12)}%</div></div><span class="stat-icon">Aa</span></div><div class="card stat"><div><div class="stat-label">Vocabulary</div><div class="stat-value">${Math.min(98, 65 + score * 10)}%</div></div><span class="stat-icon" style="background:#fff0c8">✦</span></div><div class="card stat"><div><div class="stat-label">Listening</div><div class="stat-value">${Math.min(98, 72 + score * 8)}%</div></div><span class="stat-icon" style="background:#d8edff">◒</span></div></div><div class="section-heading"><h2>Next best step</h2></div><div class="card feature-card"><div class="feature-illustration">💬</div><div class="feature-copy"><small>Recommended for your path</small><h3>Conversational English</h3><p class="small">Turn what you know into conversations that feel easy.</p></div><button class="button button-primary" data-course-details="conversation">View course</button></div>`, 'Results'); }

function renderPractice() { return shell(`<div class="section-heading" style="margin-top:0"><div><h2>Practice room</h2><p>Short, focused reps that make confidence compound.</p></div><span class="tag">${state.xp % 100} XP this session</span></div><div class="grid grid-2">${practiceCards()}</div><div class="section-heading"><h2>Quick diagnostic</h2></div><div class="card feature-card"><div class="feature-illustration" style="background:#fff0c8">🧭</div><div class="feature-copy"><small>3 questions · 3 minutes · simulated</small><h3>Check your current English</h3><p class="small">Get a rough CEFR estimate and a course recommendation.</p></div><button class="button button-primary" data-action="start-quiz">Start check</button></div>`, 'Practice'); }
function renderPracticeMode(mode) { const modes = { listening: ['Speed listening','Listen for the detail.','“I usually take the early train because it gives me a little time to read before work.”','Which transport does the speaker mention?',['The bus','The early train','A taxi','A bicycle']], grammar: ['Grammar sprint','Choose the structure that sounds natural.','If I had more time, I would learn another language.','Which phrase completes the sentence?',['will learn','would learn','am learning','learned']], speaking: ['Speaking coach','A simulated speaking practice.','Try saying: “I’m working on my English because I want to connect with more people.”','Tap the speaker, then practice aloud.',['Play sample audio','Start microphone practice','Show text alternative']], vocabulary: ['Vocabulary practice','Tap the card to reveal the meaning.','serendipity','The occurrence of finding pleasant things by chance.',['Save this word','I knew it','Review later']] }; const data = modes[mode] || modes.listening; return shell(`<button class="button button-ghost" data-route="practice">← Practice room</button><div class="two-col" style="margin-top:18px"><section class="card"><div class="eyebrow">${data[0]}</div><h2>${data[1]}</h2>${mode === 'vocabulary' ? `<div class="flashcard ${flashcardFlipped ? 'flipped' : ''}" data-action="flip-card"><div><div class="eyebrow" style="color:#d9d1ff">Tap to flip</div><h2>${data[2]}</h2><p>${flashcardFlipped ? data[3] : 'Can you remember what this word means?'}</p></div></div>` : `<div class="card" style="background:#f7f5ff;border:0;margin:20px 0;text-align:center"><div style="font-size:3rem">${mode === 'speaking' ? '◌' : '▶'}</div><p style="color:var(--navy);font-size:1.08rem;margin:0">${data[2]}</p><button class="button button-secondary" data-action="speak" data-text="${data[2]}">Play audio</button></div><h3>${data[3]}</h3>`}<div>${data[4].map((option,index) => `<button class="quiz-option" data-practice-answer="${index}"><span class="option-key">${index + 1}</span>${option}</button>`).join('')}</div><button class="button button-primary" data-action="complete-practice" data-mode="${mode}" style="margin-top:18px">Complete practice +20 XP</button></section><aside class="card"><div class="eyebrow">Your practice log</div><h3>Consistency beats intensity.</h3><p class="small">Each completed session adds XP and appears in your History. Speech recognition is available only in browsers that support it.</p><div class="progress-track"><div class="progress-fill mint" style="width:${Math.min(100, 35 + state.xp % 65)}%"></div></div><p class="small" style="margin:9px 0 0">${state.xp % 65 + 35}% weekly practice goal</p></aside></div>`, data[0]); }

function renderProgress() { const bars = [['Speaking',78],['Listening',88],['Reading',92],['Writing',70]]; return shell(`<div class="section-heading" style="margin-top:0"><div><h2>Your progress</h2><p>Notice what is getting easier.</p></div><span class="tag">${state.xp} total XP</span></div><div class="grid grid-4">${bars.map(([label,value]) => `<div class="card stat"><div><div class="stat-label">${label}</div><div class="stat-value">${value}%</div></div><span class="stat-icon">↗</span></div>`).join('')}</div><div class="two-col"><section class="card"><div class="section-heading" style="margin:0"><h3>Weekly minutes</h3><span class="muted small">Goal: 90 min</span></div><div class="chart">${[25,48,32,75,58,24,12].map((height,index) => `<div class="bar-wrap"><div class="bar" style="height:${height}%"></div><span>${['M','T','W','T','F','S','S'][index]}</span></div>`).join('')}</div></section><section class="card"><h3>Current path</h3><p class="small">Conversational English</p><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100, 20 + state.completedLessons.length * 16)}%"></div></div><div class="stat" style="margin-top:12px"><span class="small muted">Unit 4 · 18 lessons</span><strong>${Math.min(100, 20 + state.completedLessons.length * 16)}%</strong></div><button class="button button-secondary" data-route="lesson" style="margin-top:22px">Continue learning</button></section></div><div class="section-heading"><h2>Live league</h2></div><div class="card"><div class="stat"><div><h3>Starlight League</h3><p class="small">You’re ${state.xp > 600 ? 'moving up' : 'holding steady'} this week.</p></div><strong>#7</strong></div><div class="activity"><span class="avatar" style="background:#d8edff">JM</span><span class="activity-copy"><strong>Jordan Miles</strong><span>1,240 XP · #1 this week</span></span><span class="tag">Top learner</span></div><div class="activity"><span class="avatar" style="background:#d8f4e6">SK</span><span class="activity-copy"><strong>Samira Khan</strong><span>1,105 XP · #2 this week</span></span></div><div class="activity"><span class="avatar">${initials(state.profile.name)}</span><span class="activity-copy"><strong>${escapeHtml(state.profile.name)}</strong><span>${state.xp} XP · #7 this week</span></span><span class="tag">You</span></div></div>`, 'Progress'); }

function renderHistory() { return shell(`<div class="section-heading" style="margin-top:0"><div><h2>Your history</h2><p>A record of the work you’ve put in.</p></div><button class="button button-secondary" data-action="clear-history">Clear history</button></div><div class="filter-row"><input class="input search-input" id="history-search" placeholder="Search activity..." /><select class="select" id="history-filter"><option value="all">All activity</option><option value="lesson">Lessons</option><option value="xp">XP earned</option><option value="achievement">Achievements</option></select></div><div class="card" id="history-list">${historyRows(state.history)}</div>`, 'History'); }
function historyRows(items) { return items.length ? items.map(item => `<div class="activity"><span class="activity-icon">${item.icon}</span><span class="activity-copy"><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.detail)} · ${item.date}</span></span></div>`).join('') : '<div class="empty">Your completed lessons and practice sessions will appear here.</div>'; }
function renderProfile() { const achievements = [['streak','Streak master','Kept a 5-day learning streak.','🔥'],['words','Word smith','Saved your first useful word.','✦'],['lesson','First steps','Completed your first lesson.','🚀'],['quiz','Curious mind','Finished the diagnostic check.','🧭']]; return shell(`<div class="card" style="background:var(--navy);color:#fff;border:0"><div style="display:flex;align-items:center;gap:18px"><span class="avatar" style="width:62px;height:62px;font-size:1.25rem">${initials(state.profile.name)}</span><div><div class="eyebrow" style="color:#b8a9ff">${state.level} learner</div><h2 style="color:#fff;margin:5px 0">${escapeHtml(state.profile.name)}</h2><p style="color:#c9c6df;margin:0">Member since September 2026 · ${state.xp} XP</p></div><button class="button" style="margin-left:auto;background:#fff;color:var(--navy)" data-action="edit-profile">Edit profile</button></div></div><div class="section-heading"><h2>Achievements</h2><span class="muted small">${state.achievements.length}/${achievements.length} unlocked</span></div><div class="grid grid-4">${achievements.map(([id,name,desc,icon]) => `<div class="card" style="opacity:${state.achievements.includes(id) ? 1 : .5}"><div class="stat-icon" style="font-size:1.4rem">${icon}</div><h3 style="margin-top:15px">${name}</h3><p class="small">${desc}</p><span class="tag">${state.achievements.includes(id) ? 'Unlocked' : 'Locked'}</span></div>`).join('')}</div><div class="two-col" style="margin-top:30px"><section class="card"><h3>Fluency matrix</h3>${[['Speaking',78],['Listening',88],['Reading',92],['Writing',70]].map(([label,value]) => `<div style="margin-top:18px"><div class="stat"><span class="small">${label}</span><strong>${value}%</strong></div><div class="progress-track"><div class="progress-fill ${label === 'Listening' ? 'blue' : ''}" style="width:${value}%"></div></div></div>`).join('')}</section><section class="card"><h3>Sample certificate</h3><div style="border:1px solid #d9d3f8;background:#f8f6ff;text-align:center;padding:23px;border-radius:12px;margin:15px 0"><div class="eyebrow">FluentPath</div><h3 style="font-family:Fraunces,serif;font-size:1.5rem;margin:12px 0">English Level B2</h3><p class="small" style="margin:0">Sample achievement · not an official qualification</p></div><button class="button button-secondary" data-action="download-certificate">Download sample certificate</button></section></div>`, 'Profile'); }
function renderNotifications() { return shell(`<div class="section-heading" style="margin-top:0"><div><h2>Notifications</h2><p>Small nudges for a steady learning habit.</p></div><button class="button button-secondary" data-action="read-notifications">Mark all read</button></div><div class="card">${[['☀','Your daily goal is within reach','3 minutes ago'],['🔥','Your six-day streak is alive','Yesterday'],['✦','You unlocked a new practice path','Sep 16']].map(([icon,title,time],i) => `<div class="activity" style="opacity:${i < state.notifications ? 1 : .6}"><span class="activity-icon">${icon}</span><span class="activity-copy"><strong>${title}</strong><span>${time}</span></span>${i < state.notifications ? '<span class="tag">New</span>' : ''}</div>`).join('')}</div>`, 'Notifications'); }

function finishOnboarding() { state.user = true; state.level = selectedLevel; state.profile.name = 'Alex Morgan'; state.lastStudy = new Date().toISOString(); saveState(); addHistory('profile', 'Learning path created', `${selectedLevel} starting level`, '✦'); navigate('home'); toast('Your learning path is ready.'); }
function enrollCourse(id) { if (!state.enrolled.includes(id)) { state.enrolled.push(id); awardXP(30, `Enrolled in ${courses.find(course => course.id === id).title}`); toast('Course added to your learning path.'); } navigate(`course?id=${id}`); }
function completeLesson() { const index = Math.min(state.completedLessons.length, lessons.length - 1); if (!state.completedLessons.includes(index)) { state.completedLessons.push(index); awardXP(50, `Completed lesson: ${lessons[index]}`); ensureAchievement('lesson','First steps','Completed your first lesson.'); toast('+50 XP · Lesson complete'); } saveState(); page(); }
function submitQuiz() { state.quizScore = quizQuestions.reduce((score, question, index) => score + (quizAnswers[index] === question.answer ? 1 : 0), 0); awardXP(40, 'Completed diagnostic check'); ensureAchievement('quiz','Curious mind','Finished the diagnostic check.'); saveState(); navigate('quiz-result'); }
function completePractice(mode) { awardXP(20, `Completed ${mode} practice`); if (mode === 'vocabulary') ensureAchievement('words','Word smith','Saved your first useful word.'); toast('+20 XP · Practice complete'); navigate('practice'); }
function openProfileEditor() { document.body.insertAdjacentHTML('beforeend', `<div class="modal-backdrop" data-profile-modal><section class="modal" role="dialog" aria-modal="true" aria-labelledby="profile-editor-title"><div class="modal-header"><div><div class="eyebrow">Personal details</div><h2 id="profile-editor-title">Edit your profile</h2><p class="small" style="margin:0">Keep your learning space up to date.</p></div><button class="icon-button" type="button" data-action="close-profile-editor" aria-label="Close profile editor">×</button></div><form data-profile-form novalidate><div class="form-field"><label for="profile-name">Full name</label><input class="input" id="profile-name" name="name" value="${escapeHtml(state.profile.name)}" autocomplete="name" required /></div><div class="form-field"><label for="profile-email">Email address</label><input class="input" id="profile-email" name="email" type="email" value="${escapeHtml(state.profile.email)}" autocomplete="email" required /></div><div class="form-field"><label for="profile-level">English level</label><select class="select" id="profile-level" name="level"><option ${state.level === 'Beginner' ? 'selected' : ''}>Beginner</option><option ${state.level === 'Intermediate' ? 'selected' : ''}>Intermediate</option><option ${state.level === 'Advanced' ? 'selected' : ''}>Advanced</option></select></div><p class="form-error" data-profile-error role="alert"></p><div class="modal-actions"><button class="button button-ghost" type="button" data-action="close-profile-editor">Cancel</button><button class="button button-primary" type="submit">Save changes</button></div></form></section></div>`); const modal = document.querySelector('[data-profile-modal]'); modal.querySelector('#profile-name').focus(); modal.querySelector('[data-profile-form]').addEventListener('submit', saveProfileEditor); modal.addEventListener('click', event => { if (event.target === modal) closeProfileEditor(); }); modal.querySelectorAll('[data-action="close-profile-editor"]').forEach(button => button.addEventListener('click', closeProfileEditor)); }
function closeProfileEditor() { document.querySelector('[data-profile-modal]')?.remove(); }
function saveProfileEditor(event) { event.preventDefault(); const form = event.currentTarget; const formData = new FormData(form); const name = String(formData.get('name') || '').trim(); const email = String(formData.get('email') || '').trim(); const level = String(formData.get('level') || 'Intermediate'); const error = form.querySelector('[data-profile-error]'); if (name.length < 2) { error.textContent = 'Please enter your full name.'; return; } if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { error.textContent = 'Please enter a valid email address.'; return; } state.profile = { ...state.profile, name, email }; state.level = level; selectedLevel = level; saveState(); closeProfileEditor(); page(); toast('Profile updated successfully.'); }
function bindEvents() { document.querySelectorAll('[data-route]').forEach(button => button.addEventListener('click', () => navigate(button.dataset.route))); document.querySelectorAll('[data-level]').forEach(button => button.addEventListener('click', () => { selectedLevel = button.dataset.level; page(); })); document.querySelectorAll('[data-enroll]').forEach(button => button.addEventListener('click', () => enrollCourse(button.dataset.enroll))); document.querySelectorAll('[data-course-details]').forEach(button => button.addEventListener('click', () => navigate(`course?id=${button.dataset.courseDetails}`))); document.querySelectorAll('[data-practice]').forEach(button => button.addEventListener('click', () => navigate(`practice-${button.dataset.practice}`))); document.querySelectorAll('[data-answer]').forEach(button => button.addEventListener('click', () => { quizAnswers[quizIndex] = Number(button.dataset.answer); page(); })); document.querySelectorAll('[data-practice-answer]').forEach(button => button.addEventListener('click', () => { button.classList.add('selected'); }));
  const action = (name, callback) => document.querySelectorAll(`[data-action="${name}"]`).forEach(button => button.addEventListener('click', callback));
  action('demo-login', () => { state.user = true; state.level = 'Intermediate'; saveState(); navigate('home'); }); action('finish-onboarding', finishOnboarding); action('save-word', () => { if (!state.savedWords.includes('serendipity')) state.savedWords.push('serendipity'); ensureAchievement('words','Word smith','Saved your first useful word.'); saveState(); page(); }); action('complete-lesson', completeLesson); action('start-quiz', () => { quizIndex = 0; quizAnswers = {}; navigate('quiz'); }); action('quiz-next', () => { quizIndex += 1; page(); }); action('quiz-back', () => { quizIndex -= 1; page(); }); action('submit-quiz', submitQuiz); action('flip-card', () => { flashcardFlipped = !flashcardFlipped; page(); }); action('complete-practice', event => completePractice(event.currentTarget.dataset.mode)); action('notifications', () => navigate('notifications')); action('read-notifications', () => { state.notifications = 0; saveState(); page(); }); action('clear-history', () => { state.history = []; saveState(); page(); }); action('download-certificate', () => toast('Sample certificate download prepared.')); action('speak', event => { if ('speechSynthesis' in window) window.speechSynthesis.speak(new SpeechSynthesisUtterance(event.currentTarget.dataset.text)); else toast('Audio playback is not supported in this browser.'); }); action('edit-profile', openProfileEditor);
  const search = document.querySelector('#course-search'); const category = document.querySelector('#course-category'); const level = document.querySelector('#course-level'); const filterCourses = () => { const query = (search?.value || '').toLowerCase(); const items = courses.filter(course => (!query || `${course.title} ${course.description}`.toLowerCase().includes(query)) && (!category || category.value === 'all' || course.category === category.value) && (!level || level.value === 'all' || course.level === level.value)); const grid = document.querySelector('#course-grid'); if (grid) grid.innerHTML = courseCards(items); bindEvents(); }; search?.addEventListener('input', filterCourses); category?.addEventListener('change', filterCourses); level?.addEventListener('change', filterCourses);
  const historySearch = document.querySelector('#history-search'); const historyFilter = document.querySelector('#history-filter'); const filterHistory = () => { const query = (historySearch?.value || '').toLowerCase(); const type = historyFilter?.value || 'all'; const items = state.history.filter(item => (!query || `${item.title} ${item.detail}`.toLowerCase().includes(query)) && (type === 'all' || item.type === type)); const list = document.querySelector('#history-list'); if (list) list.innerHTML = historyRows(items); }; historySearch?.addEventListener('input', filterHistory); historyFilter?.addEventListener('change', filterHistory); }

function renderQuizResult() { const score = state.quizScore || 0; const total = quizQuestions.length; const percentage = Math.round((score / total) * 100); const level = percentage >= 88 ? 'B2 estimate' : percentage >= 63 ? 'B1 estimate' : 'A2 estimate'; const message = percentage >= 88 ? 'You are showing strong control and useful range.' : percentage >= 63 ? 'You have a solid base to build into confident fluency.' : 'You have a clear foundation and a practical next step.'; return shell(`<div class="hero"><div class="eyebrow" style="color:#b8a9ff">Assessment complete · Demo result</div><h1>${level}</h1><p>${message} You answered ${score} of ${total} questions correctly. This is an estimate for learning guidance, not an official certification.</p><div class="hero-meta"><span><strong>${percentage}%</strong>overall score</span><span><strong>${score}/${total}</strong>correct answers</span><span><strong>8 min</strong>assessment time</span></div><button class="button" style="background:var(--yellow);color:var(--navy);margin-top:22px" data-route="courses">Explore recommended course →</button></div><div class="grid grid-3"><div class="card stat"><div><div class="stat-label">Grammar & structure</div><div class="stat-value">${Math.min(98, 54 + score * 5)}%</div></div><span class="stat-icon">${uiIcon('text')}</span></div><div class="card stat"><div><div class="stat-label">Vocabulary in context</div><div class="stat-value">${Math.min(98, 60 + score * 4)}%</div></div><span class="stat-icon">${uiIcon('spark')}</span></div><div class="card stat"><div><div class="stat-label">Conversation sense</div><div class="stat-value">${Math.min(98, 58 + score * 5)}%</div></div><span class="stat-icon">${uiIcon('mic')}</span></div></div><div class="two-col"><section class="card"><div class="section-heading" style="margin:0"><div><div class="eyebrow">Recommended next step</div><h3 style="font-size:1.25rem;margin-top:7px">Conversational English</h3></div><span class="tag">${state.level} path</span></div><p class="small">Turn your language knowledge into conversations that feel natural, with guided listening and useful expressions.</p><div class="info-grid"><div class="info-item"><strong>18 lessons</strong><span>Short, focused units</span></div><div class="info-item"><strong>6 weeks</strong><span>Flexible pace</span></div><div class="info-item"><strong>4.9 rating</strong><span>Learner favorite</span></div></div><button class="button button-primary" data-course-details="conversation" style="margin-top:20px">View course details</button></section><aside class="card quiz-guide"><div class="eyebrow">Keep building</div><h3>Three useful habits</h3><div class="quiz-tip"><b>01</b><span class="small">Listen for meaning, not every single word.</span></div><div class="quiz-tip"><b>02</b><span class="small">Save phrases you can use in real conversations.</span></div><div class="quiz-tip"><b>03</b><span class="small">Return for short practice sessions often.</span></div></aside></div>`, 'Results'); }
function enhanceRenderedPage() { const routeName = currentRoute().split('?')[0]; const main = document.querySelector('.main'); if (!main || main.querySelector('[data-enhancement]')) return; if (routeName === 'home') { main.insertAdjacentHTML('beforeend', `<section class="card" data-enhancement style="margin-top:18px"><div class="section-heading" style="margin:0"><div><div class="eyebrow">Your plan for today</div><h3 style="font-size:1.25rem;margin-top:7px">A focused 25-minute session</h3></div><span class="tag">12 min complete</span></div><div class="plan-list"><div class="plan-row"><span>01</span><span><strong>Resume Conversational English</strong><small>6 min · Continue Unit 4 with one useful follow-up phrase.</small></span><button class="button button-ghost" style="margin-left:auto" data-route="lesson">Open</button></div><div class="plan-row"><span>02</span><span><strong>Practice your listening</strong><small>8 min · Train your ear for natural rhythm and detail.</small></span><button class="button button-ghost" style="margin-left:auto" data-practice="listening">Start</button></div><div class="plan-row"><span>03</span><span><strong>Review one saved word</strong><small>4 min · Turn recognition into recall.</small></span><button class="button button-ghost" style="margin-left:auto" data-practice="vocabulary">Review</button></div></div></section>`); } if (routeName === 'quiz') { const aside = main.querySelector('aside'); aside?.insertAdjacentHTML('beforeend', `<div class="card quiz-guide" data-enhancement style="margin-top:18px"><div class="eyebrow">Assessment guide</div><h3>Take your time and use the context.</h3><p class="small">You can change an answer before moving forward. Each explanation shows the language idea behind the answer.</p><div class="quiz-tip"><b>01</b><span class="small">Read the whole sentence before choosing.</span></div><div class="quiz-tip"><b>02</b><span class="small">Look for time markers and sentence structure.</span></div><div class="quiz-tip"><b>03</b><span class="small">Your result is a demo estimate, not certification.</span></div></div>`); } if (routeName === 'quiz-result') { main.insertAdjacentHTML('beforeend', `<section class="card" data-enhancement style="margin-top:18px"><div class="section-heading" style="margin:0"><div><div class="eyebrow">Assessment breakdown</div><h3 style="font-size:1.25rem;margin-top:7px">What this result tells you</h3></div><span class="tag">3 skill signals</span></div><div class="info-grid"><div class="info-item"><strong>Grammar</strong><span>How accurately you build sentences and use time expressions.</span></div><div class="info-item"><strong>Vocabulary</strong><span>How well you recognize useful meaning in context.</span></div><div class="info-item"><strong>Listening</strong><span>How confidently you follow natural English details.</span></div></div></section>`); } }

function enhanceProgressPage() { if (currentRoute().split('?')[0] !== 'progress' || document.querySelector('[data-progress-enhancement]')) return; const main = document.querySelector('.main'); const heading = main?.querySelector('.section-heading'); if (!main || !heading) return; heading.insertAdjacentHTML('afterend', `<section class="card progress-summary" data-progress-enhancement><div><div class="eyebrow" style="color:#b8a9ff">Your learning pulse</div><h3>Steady work is adding up.</h3><p>${state.completedLessons.length ? 'You have completed ' + state.completedLessons.length + ' lesson' + (state.completedLessons.length === 1 ? '' : 's') + ' this week.' : 'Start with one focused session and build your first win.'}</p></div><div class="right"><strong style="font-size:2rem">${Math.min(100, 20 + state.completedLessons.length * 16)}%</strong><div class="small" style="color:#c9c6df">path complete</div></div></section>`); const skillCards = main.querySelectorAll('.grid.grid-4 > .card.stat'); skillCards.forEach(card => { const value = Number(card.querySelector('.stat-value')?.textContent?.replace('%', '') || 0); card.classList.add('skill-card'); card.style.setProperty('--skill-progress', `${value / 100}`); }); }
function enhanceIcons() { document.querySelectorAll('.icon-button').forEach(button => { if (button.dataset.iconEnhanced) return; if (button.dataset.action === 'notifications') { const badge = button.querySelector('.badge-dot')?.outerHTML || ''; button.innerHTML = `${uiIcon('bell')}${badge}`; } button.dataset.iconEnhanced = 'true'; }); document.querySelectorAll('.sidebar-foot .nav-button').forEach(button => { if (!button.dataset.iconEnhanced) { button.innerHTML = `${uiIcon('settings')}<span>Profile & settings</span>`; button.dataset.iconEnhanced = 'true'; } }); document.querySelectorAll('.practice-icon, .stat-icon').forEach(container => { if (container.dataset.iconEnhanced) return; const symbol = container.textContent.trim(); container.innerHTML = uiIcon(symbol); container.dataset.iconEnhanced = 'true'; }); }
function enhanceQuizMeta() { if (currentRoute().split('?')[0] !== 'quiz') return; const duration = document.querySelector('.activity-copy strong'); if (duration) duration.textContent = 'About 8 minutes'; }
function cleanupQuizResult() { if (currentRoute().split('?')[0] === 'quiz-result') document.querySelectorAll('[data-enhancement]').forEach(element => element.remove()); }
document.addEventListener('click', event => { const routeButton = event.target.closest('[data-enhancement] [data-route]'); const practiceButton = event.target.closest('[data-enhancement] [data-practice]'); if (routeButton) navigate(routeButton.dataset.route); if (practiceButton) navigate(`practice-${practiceButton.dataset.practice}`); });
window.addEventListener('hashchange', page);
window.addEventListener('hashchange', () => setTimeout(enhanceRenderedPage, 0));
window.addEventListener('hashchange', () => setTimeout(enhanceProgressPage, 0));
window.addEventListener('hashchange', () => setTimeout(enhanceIcons, 0));
window.addEventListener('hashchange', () => setTimeout(enhanceQuizMeta, 0));
window.addEventListener('hashchange', () => setTimeout(cleanupQuizResult, 0));
page();
enhanceRenderedPage();
enhanceProgressPage();
enhanceIcons();
enhanceQuizMeta();
cleanupQuizResult();
